1	const std = @import("std");
2	const array_mod = @import("../array/array.zig");
3	const bitmap = @import("../bitmap.zig");
4	const buffer = @import("../buffer.zig");
5	const chunked_array_mod = @import("../chunked_array.zig");
6	const concat_array_refs = @import("../concat_array_refs.zig");
7	const core = @import("core.zig");
8	const iterators = @import("iterators.zig");
9	const accessors = @import("datum_accessors.zig");
10	const builders = @import("datum_builders.zig");
11	const common = @import("datum_common.zig");
12	
13	const DataType = core.DataType;
14	const storageDataType = concat_array_refs.storageDataType;
15	const ArrayRef = core.ArrayRef;
16	const ChunkedArray = core.ChunkedArray;
17	const Datum = core.Datum;
18	const KernelError = core.KernelError;
19	const FilterOptions = core.FilterOptions;
20	
21	const inferBinaryExecLen = iterators.inferBinaryExecLen;
22	const inferNaryExecLen = iterators.inferNaryExecLen;
23	const sameDataTypes = iterators.sameDataTypes;
24	
25	const mapArrayReadError = common.mapArrayReadError;
26	
27	const ChunkLookup = struct {
28	    chunk: *const ArrayRef,
29	    local_index: usize,
30	};
31	
32	fn lookupChunkAt(chunks: ChunkedArray, logical_index: usize) ?ChunkLookup {
33	    if (logical_index >= chunks.len()) return null;
34	
35	    var remaining = logical_index;
36	    var chunk_index: usize = 0;
37	    while (chunk_index < chunks.numChunks()) : (chunk_index += 1) {
38	        const chunk_ref = chunks.chunk(chunk_index);
39	        const chunk_len = chunk_ref.data().length;
40	        if (remaining < chunk_len) {
41	            return .{
42	                .chunk = chunk_ref,
43	                .local_index = remaining,
44	            };
45	        }
46	        remaining -= chunk_len;
47	    }
48	    return null;
49	}
50	
51	const PredicateDecision = enum {
52	    keep,
53	    drop,
54	    emit_null,
55	};
56	
57	fn datumTakeChunkedNullable(
58	    allocator: std.mem.Allocator,
59	    chunks: ChunkedArray,
60	    out_type: DataType,
61	    indices: anytype,
62	) KernelError!Datum {
63	    if (indices.len == 0) {
64	        return Datum.fromChunked(chunks.slice(allocator, 0, 0) catch |err| return common.mapChunkedError(err));
65	    }
66	    var pieces: std.ArrayList(ArrayRef) = .empty;
67	    defer releasePieces(allocator, &pieces);
68	    try takeChunked(allocator, chunks, out_type, indices, &pieces);
69	    return Datum.fromChunked(ChunkedArray.init(allocator, out_type, pieces.items) catch |err| return common.mapChunkedError(err));
70	}
71	
72	fn releasePieces(allocator: std.mem.Allocator, pieces: *std.ArrayList(ArrayRef)) void {
73	    for (pieces.items) |*piece| piece.release();
74	    pieces.deinit(allocator);
75	}
76	
77	/// Chunk holding logical row `idx` (< total); tries `hint` first so sorted indices stay O(1).
78	fn chunkOf(starts: []const usize, hint: usize, idx: usize) usize {
79	    if (starts[hint] <= idx and idx < starts[hint + 1]) return hint;
80	    var lo: usize = 0;
81	    var hi: usize = starts.len - 1;
82	    while (lo < hi) {
83	        const mid = lo + (hi - lo) / 2;
84	        if (starts[mid + 1] <= idx) lo = mid + 1 else hi = mid;
85	    }
86	    return lo;
87	}
88	
89	/// Take from a chunked datum, appending the output pieces in order. Indices are split into runs
90	/// that stay inside one chunk: few runs (filters, sorted or clustered takes) take each run from
91	/// its chunk with the array kernels; many runs (random takes) concat the chunks once and take
92	/// from that, unless the chunks do not concat (e.g. different dictionaries).
93	fn takeChunked(
94	    allocator: std.mem.Allocator,
95	    chunks: ChunkedArray,
96	    out_type: DataType,
97	    indices: anytype,
98	    pieces: *std.ArrayList(ArrayRef),
99	) KernelError!void {
100	    const n = chunks.numChunks();
101	    if (n == 0 or !hasTakeKernel(out_type)) {
102	        // Per-row path: one 1-row slice (or null row) per index.
103	        try pieces.ensureUnusedCapacity(allocator, indices.len);
104	        for (indices) |m| pieces.appendAssumeCapacity(if (@as(?usize, m)) |idx|
105	            try accessors.datumElementArrayAt(allocator, Datum.fromChunked(chunks), idx)
106	        else
107	            try builders.buildNullLikeArray(allocator, out_type, 1));
108	        return;
109	    }
110	    const starts = allocator.alloc(usize, n + 1) catch return error.OutOfMemory;
111	    defer allocator.free(starts);
112	    starts[0] = 0;
113	    for (chunks.chunks(), 0..) |c, i| starts[i + 1] = std.math.add(usize, starts[i], c.data().length) catch return error.Overflow;
114	    try checkIndices(indices, starts[n]);
115	
116	    // ponytail: 64 ~ cost of one kernel call per run vs. one concat row; retune if mixed shapes get hot.
117	    const max_runs = starts[n] / 64;
118	    var runs: usize = 1;
119	    var cur: usize = 0;
120	    var have = false; // the current run holds a non-null index
121	    for (indices) |m| {
122	        const c = chunkOf(starts, cur, @as(?usize, m) orelse continue);
123	        if (have and c != cur) runs += 1;
124	        if (runs > max_runs) break;
125	        cur = c;
126	        have = true;
127	    }
128	    if (n > 1 and runs > max_runs) concat_first: {
129	        var flat = concat_array_refs.concatArrayRefs(allocator, out_type, chunks.chunks()) catch |err| switch (err) {
130	            error.OutOfMemory => return error.OutOfMemory,
131	            else => break :concat_first,
132	        };
133	        defer flat.release();
134	        return appendPiece(allocator, pieces, try takeChild(allocator, flat, indices));
135	    }
136	
137	    const E = @typeInfo(@TypeOf(indices)).pointer.child;
138	    const local = allocator.alloc(E, indices.len) catch return error.OutOfMemory;
139	    defer allocator.free(local);
140	    var run_start: usize = 0;
141	    cur = 0;
142	    have = false;
143	    for (indices, local, 0..) |m, *l, i| {
144	        if (@as(?usize, m)) |idx| {
145	            const c = chunkOf(starts, cur, idx);
146	            if (have and c != cur) {
147	                try appendPiece(allocator, pieces, try takeChild(allocator, chunks.chunk(cur).*, @as([]const E, local[run_start..i])));
148	                run_start = i;
149	            }
150	            cur = c;
151	            have = true;
152	            l.* = if (comptime E == u32) @intCast(idx - starts[c]) else idx - starts[c];
153	        } else l.* = m;
154	    }
155	    try appendPiece(allocator, pieces, try takeChild(allocator, chunks.chunk(cur).*, @as([]const E, local[run_start..])));
156	}
157	
158	fn appendPiece(allocator: std.mem.Allocator, pieces: *std.ArrayList(ArrayRef), piece: ArrayRef) KernelError!void {
159	    pieces.append(allocator, piece) catch {
160	        var owned = piece;
161	        owned.release();
162	        return error.OutOfMemory;
163	    };
164	}
165	
166	/// Takes `indices` from `child` with the array kernels (or the per-row fallback).
167	fn takeChild(allocator: std.mem.Allocator, child: ArrayRef, indices: anytype) KernelError!ArrayRef {
168	    var taken = try datumTakeArrayLikeNullable(allocator, Datum.fromArray(child), child.data().data_type, indices);
169	    if (taken != .array) {
170	        taken.release();
171	        return error.InvalidInput;
172	    }
173	    return taken.array;
174	}
175	
176	/// Direct gather for fixed-width and boolean arrays: output buffers are allocated once, every
177	/// slot copies its value without a branch, and validity is packed 8 rows per byte (gatherBits).
178	/// `indices` is `[]const ?usize` (null = null row) or dense `[]const usize` / `[]const u32`.
179	/// Dictionary arrays gather their indices and share the dictionary.
180	/// Returns null for layouts it does not handle so callers fall back to slice+concat.
181	fn takeFixedWidthArray(
182	    allocator: std.mem.Allocator,
183	    src: *const array_mod.ArrayData,
184	    indices: anytype,
185	) KernelError!?ArrayRef {
186	    const layout = storageDataType(src.data_type);
187	    const byte_width = (try fixedByteWidth(layout)) orelse return null;
188	    if (src.buffers.len != 2) return null;
189	    const is_bool = layout == .bool;
190	    const src_bytes = src.buffers[1].data;
191	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
192	    const src_need = if (is_bool) bitmap.byteLength(src_end) else std.math.mul(usize, src_end, byte_width) catch return error.Overflow;
193	    if (src_bytes.len < src_need) return error.InvalidInput;
194	    const src_validity = try validityBytes(src, src_end);
195	    try checkIndices(indices, src.length);
196	
197	    const out_len = indices.len;
198	    const values_len = if (is_bool) bitmap.byteLength(out_len) else out_len * byte_width;
199	    // Bool values are OR-ed bits (need zeroed memory); fixed-width slots are all written below.
200	    var values = (if (is_bool) buffer.OwnedBuffer.init(allocator, values_len) else buffer.OwnedBuffer.initUninit(allocator, values_len)) catch return error.OutOfMemory;
201	    errdefer values.deinit();
202	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
203	    errdefer validity.deinit();
204	
205	    const null_count = out_len - gatherBits(validity.data, src_validity, src.offset, indices);
206	    if (is_bool) {
207	        _ = gatherBits(values.data, src_bytes, src.offset, indices);
208	    } else switch (byte_width) {
209	        inline 1, 2, 4, 8, 16, 32 => |w| {
210	            const E = [w]u8;
211	            const s = std.mem.bytesAsSlice(E, src_bytes[src.offset * w ..][0 .. src.length * w]);
212	            const d = std.mem.bytesAsSlice(E, values.data[0..values_len]);
213	            for (indices, d) |m, *o| o.* = if (@as(?usize, m)) |j| s[j] else @splat(0);
214	        },
215	        else => for (indices, 0..) |m, i| {
216	            const o = values.data[i * byte_width ..][0..byte_width];
217	            if (@as(?usize, m)) |j| @memcpy(o, src_bytes[(src.offset + j) * byte_width ..][0..byte_width]) else @memset(o, 0);
218	        },
219	    }
220	
221	    var buffers: [2]buffer.SharedBuffer = undefined;
222	    buffers[0] = if (null_count == 0) blk: {
223	        validity.deinit();
224	        break :blk buffer.SharedBuffer.empty;
225	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
226	    errdefer buffers[0].release();
227	    buffers[1] = values.toShared(values_len) catch return error.OutOfMemory;
228	    errdefer buffers[1].release();
229	
230	    const out = ArrayRef.fromOwnedInlineBuffers(allocator, .{
231	        .data_type = src.data_type,
232	        .length = out_len,
233	        .null_count = null_count,
234	        .buffers = buffers[0..],
235	        .dictionary = src.dictionary,
236	    }) catch return error.OutOfMemory;
237	    if (src.dictionary) |dict| _ = dict.retain();
238	    return out;
239	}
240	
241	/// Value width of a fixed-width layout (0 for bool, index width for dictionaries), else null.
242	fn fixedByteWidth(layout: DataType) KernelError!?usize {
243	    const width: usize = switch (layout) {
244	        .bool => return 0,
245	        .uint8, .int8 => 1,
246	        .uint16, .int16, .half_float => 2,
247	        .uint32, .int32, .float, .date32, .time32, .interval_months, .decimal32 => 4,
248	        .uint64, .int64, .double, .date64, .time64, .timestamp, .duration, .interval_day_time, .decimal64 => 8,
249	        .decimal128, .interval_month_day_nano => 16,
250	        .decimal256 => 32,
251	        .fixed_size_binary => |f| std.math.cast(usize, f.byte_width) orelse return error.InvalidInput,
252	        .dictionary => |d| d.index_type.bit_width / 8,
253	        else => return null,
254	    };
255	    return if (width == 0) null else width; // zero-width: per-row path, as before
256	}
257	
258	/// The source validity bytes (null when there is no bitmap), checked to cover `src_end` bits.
259	fn validityBytes(src: *const array_mod.ArrayData, src_end: usize) KernelError!?[]const u8 {
260	    const v = src.validity() orelse return null;
261	    if (v.data.len < bitmap.byteLength(src_end)) return error.InvalidInput;
262	    return v.data;
263	}
264	
265	/// Index slices without null entries (`[]const usize`, `[]const u32`).
266	fn isDense(comptime I: type) bool {
267	    return I == []const usize or I == []const u32;
268	}
269	
270	/// Every non-null index must be < len. Dense slices use a max-reduce, which vectorizes.
271	fn checkIndices(indices: anytype, len: usize) KernelError!void {
272	    const I = @TypeOf(indices);
273	    if (comptime isDense(I)) {
274	        if (indices.len > 0 and std.mem.max(@typeInfo(I).pointer.child, indices) >= len) return error.InvalidInput;
275	    } else for (indices) |maybe| if (maybe) |idx| {
276	        if (idx >= len) return error.InvalidInput;
277	    };
278	}
279	
280	/// Bit i of zeroed `dst` = indices[i] is non-null and bit `offset + indices[i]` of `src` is set
281	/// (`src == null` means all set). 8 indices per output byte, no data-dependent branch
282	/// (arrow-rs take_bits). Returns the number of set bits. Callers bounds-check indices and `src`.
283	fn gatherBits(dst: []u8, src: ?[]const u8, offset: usize, indices: anytype) usize {
284	    var set: usize = 0;
285	    var i: usize = 0;
286	    while (i + 8 <= indices.len) : (i += 8) {
287	        var byte: u8 = 0;
288	        inline for (0..8) |k| byte |= bitOf(src, offset, indices[i + k]) << k;
289	        dst[i >> 3] = byte;
290	        set += @popCount(byte);
291	    }
292	    if (i < indices.len) {
293	        var byte: u8 = 0;
294	        for (indices[i..], 0..) |m, k| byte |= bitOf(src, offset, m) << @intCast(k);
295	        dst[i >> 3] = byte;
296	        set += @popCount(byte);
297	    }
298	    return set;
299	}
300	
301	inline fn bitOf(src: ?[]const u8, offset: usize, maybe: anytype) u8 {
302	    const idx = @as(?usize, maybe) orelse return 0;
303	    const s = src orelse return 1;
304	    const j = offset + idx;
305	    return (s[j >> 3] >> @intCast(j & 7)) & 1;
306	}
307	
308	fn validAt(src_validity: ?bitmap.ValidityBitmap, j: usize) bool {
309	    const v = src_validity orelse return true;
310	    return bitmap.bitIsSet(v.data, j);
311	}
312	
313	/// Value range of row `j` (physical index) in an offsets buffer; `limit` bounds the end.
314	fn offsetRange(comptime T: type, offsets: []const T, j: usize, limit: usize) KernelError![2]usize {
315	    const lo = std.math.cast(usize, offsets[j]) orelse return error.InvalidInput;
316	    const hi = std.math.cast(usize, offsets[j + 1]) orelse return error.InvalidInput;
317	    if (hi < lo or hi > limit) return error.InvalidInput;
318	    return .{ lo, hi };
319	}
320	
321	/// Direct gather for string/binary (i32 or i64 offsets): pass 1 bounds-checks offsets and sizes
322	/// the value buffer, pass 2 copies offsets + bytes, validity is packed by gatherBits.
323	/// Null source rows keep their bytes (usually none), like arrow-rs. Returns null for other layouts.
324	fn takeBinaryArray(
325	    comptime T: type,
326	    allocator: std.mem.Allocator,
327	    src: *const array_mod.ArrayData,
328	    indices: anytype,
329	) KernelError!?ArrayRef {
330	    if (src.buffers.len != 3) return null;
331	    const offsets = src.buffers[1].typedSlice(T) catch return error.InvalidInput;
332	    const bytes = src.buffers[2].data;
333	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
334	    if (offsets.len <= src_end) return error.InvalidInput;
335	    const src_validity = try validityBytes(src, src_end);
336	    try checkIndices(indices, src.length);
337	
338	    var total: usize = 0;
339	    for (indices) |maybe| {
340	        const idx: usize = @as(?usize, maybe) orelse continue;
341	        const r = try offsetRange(T, offsets, src.offset + idx, bytes.len);
342	        total = std.math.add(usize, total, r[1] - r[0]) catch return error.Overflow;
343	    }
344	    if (total > std.math.maxInt(T)) return error.Overflow;
345	
346	    const out_len = indices.len;
347	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, (out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
348	    errdefer out_offsets.deinit();
349	    // 16 bytes of slack so short values move as one fixed 16-byte copy (copyShort).
350	    var out_bytes = buffer.OwnedBuffer.initUninit(allocator, total + 16) catch return error.OutOfMemory;
351	    errdefer out_bytes.deinit();
352	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
353	    errdefer validity.deinit();
354	
355	    const o = out_offsets.typedSlice(T);
356	    o[0] = 0;
357	    var pos: usize = 0;
358	    for (indices, 0..) |maybe, i| {
359	        if (@as(?usize, maybe)) |idx| {
360	            const j = src.offset + idx;
361	            const lo: usize = @intCast(offsets[j]);
362	            const n: usize = @intCast(offsets[j + 1] - offsets[j]);
363	            copyShort(out_bytes.data[pos..], bytes, lo, n);
364	            pos += n;
365	        }
366	        o[i + 1] = @intCast(pos);
367	    }
368	    const null_count = out_len - gatherBits(validity.data, src_validity, src.offset, indices);
369	
370	    var buffers: [3]buffer.SharedBuffer = undefined;
371	    buffers[0] = if (null_count == 0) blk: {
372	        validity.deinit();
373	        break :blk buffer.SharedBuffer.empty;
374	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
375	    errdefer buffers[0].release();
376	    buffers[1] = out_offsets.toShared((out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
377	    errdefer buffers[1].release();
378	    buffers[2] = out_bytes.toShared(total) catch return error.OutOfMemory;
379	    errdefer buffers[2].release();
380	
381	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
382	        .data_type = src.data_type,
383	        .length = out_len,
384	        .null_count = null_count,
385	        .buffers = buffers[0..],
386	    }) catch return error.OutOfMemory;
387	}
388	
389	/// Copies `src[lo..][0..n]` to the front of `dst`. Values of at most 16 bytes move as one fixed
390	/// 16-byte load/store when both sides have room; `dst` bytes past `n` are scratch.
391	inline fn copyShort(dst: []u8, src: []const u8, lo: usize, n: usize) void {
392	    if (n <= 16 and lo + 16 <= src.len and dst.len >= 16) {
393	        dst[0..16].* = src[lo..][0..16].*;
394	    } else @memcpy(dst[0..n], src[lo..][0..n]);
395	}
396	
397	/// Direct gather for list/large_list: rebuilds offsets + validity and takes the child once
398	/// with the expanded child indices (recursing into the fast kernels). Returns null for other layouts.
399	fn takeListArray(
400	    comptime T: type,
401	    allocator: std.mem.Allocator,
402	    src: *const array_mod.ArrayData,
403	    indices: anytype,
404	) KernelError!?ArrayRef {
405	    if (src.buffers.len != 2 or src.children.len != 1) return null;
406	    const offsets = src.buffers[1].typedSlice(T) catch return error.InvalidInput;
407	    const child = src.children[0];
408	    const child_len = child.data().length;
409	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
410	    if (offsets.len <= src_end) return error.InvalidInput;
411	    const src_validity = src.validity();
412	
413	    var total: usize = 0;
414	    var null_count: usize = 0;
415	    for (indices) |maybe| {
416	        const idx: usize = @as(?usize, maybe) orelse {
417	            null_count += 1;
418	            continue;
419	        };
420	        if (idx >= src.length) return error.InvalidInput;
421	        const j = src.offset + idx;
422	        if (!validAt(src_validity, j)) {
423	            null_count += 1;
424	            continue;
425	        }
426	        const r = try offsetRange(T, offsets, j, child_len);
427	        total = std.math.add(usize, total, r[1] - r[0]) catch return error.Overflow;
428	    }
429	    if (total > std.math.maxInt(T)) return error.Overflow;
430	
431	    const child_indices = allocator.alloc(usize, total) catch return error.OutOfMemory;
432	    defer allocator.free(child_indices);
433	    const out_len = indices.len;
434	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, (out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
435	    errdefer out_offsets.deinit();
436	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
437	    errdefer validity.deinit();
438	
439	    const o = out_offsets.typedSlice(T);
440	    o[0] = 0;
441	    var pos: usize = 0;
442	    for (indices, 0..) |maybe, i| {
443	        if (@as(?usize, maybe)) |idx| {
444	            const j = src.offset + idx;
445	            if (validAt(src_validity, j)) {
446	                const lo: usize = @intCast(offsets[j]);
447	                const hi: usize = @intCast(offsets[j + 1]);
448	                for (child_indices[pos..][0 .. hi - lo], lo..) |*ci, k| ci.* = k;
449	                pos += hi - lo;
450	                bitmap.setBit(validity.data, i);
451	            }
452	        }
453	        o[i + 1] = @intCast(pos);
454	    }
455	
456	    const children = try takeChildren(allocator, src.children, null, @as([]const usize, child_indices));
457	    errdefer releaseChildren(allocator, children);
458	
459	    var buffers: [2]buffer.SharedBuffer = undefined;
460	    buffers[0] = if (null_count == 0) blk: {
461	        validity.deinit();
462	        break :blk buffer.SharedBuffer.empty;
463	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
464	    errdefer buffers[0].release();
465	    buffers[1] = out_offsets.toShared((out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
466	    errdefer buffers[1].release();
467	
468	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
469	        .data_type = src.data_type,
470	        .length = out_len,
471	        .null_count = null_count,
472	        .buffers = buffers[0..],
473	        .children = children,
474	    }) catch return error.OutOfMemory;
475	}
