477	/// Takes the same `indices` from every child. With a struct/union `parent`, children are either
478	/// row-aligned (same length as the parent, as `ArrayRef.slice` makes them) or in parent
479	/// coordinates (row = offset + idx); without one, indices are child rows.
480	fn takeChildren(allocator: std.mem.Allocator, src_children: []const ArrayRef, parent: ?*const array_mod.ArrayData, indices: anytype) KernelError![]ArrayRef {
481	    const children = allocator.alloc(ArrayRef, src_children.len) catch return error.OutOfMemory;
482	    var built: usize = 0;
483	    errdefer {
484	        for (children[0..built]) |*child| child.release();
485	        allocator.free(children);
486	    }
487	    for (src_children, children) |child, *out| {
488	        const p = parent orelse child.data();
489	        if (child.data().length == p.length) {
490	            out.* = try takeChild(allocator, child, indices);
491	        } else {
492	            if (child.data().length < p.offset + p.length) return error.InvalidInput;
493	            var window = child.slice(p.offset, p.length) catch return error.OutOfMemory;
494	            defer window.release();
495	            out.* = try takeChild(allocator, window, indices);
496	        }
497	        built += 1;
498	    }
499	    return children;
500	}
501	
502	fn releaseChildren(allocator: std.mem.Allocator, children: []ArrayRef) void {
503	    for (children) |*child| child.release();
504	    allocator.free(children);
505	}
