507	/// Direct take for struct and sparse union: every child is taken with the same indices (null
508	/// indices take null child rows; null struct rows keep their child rows, like arrow-rs).
509	/// Struct validity is gathered; union type ids are gathered (null index: the first type id).
510	fn takeStructLikeArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!ArrayRef {
511	    const is_union = storageDataType(src.data_type) == .sparse_union;
512	    if (src.buffers.len < 1) return error.InvalidInput;
513	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
514	    try checkIndices(indices, src.length);
515	    const out_len = indices.len;
516	
517	    var head = buffer.OwnedBuffer.init(allocator, if (is_union) out_len else bitmap.byteLength(out_len)) catch return error.OutOfMemory;
518	    errdefer head.deinit();
519	    var null_count: usize = 0;
520	    if (is_union) {
521	        const ids = src.buffers[0].data;
522	        if (ids.len < src_end) return error.InvalidInput;
523	        const declared = storageDataType(src.data_type).sparse_union.type_ids;
524	        if (declared.len == 0 and out_len > 0) return error.InvalidInput;
525	        const first: u8 = if (declared.len > 0) @bitCast(declared[0]) else 0;
526	        for (indices, head.data[0..out_len]) |m, *o| o.* = if (@as(?usize, m)) |j| ids[src.offset + j] else first;
527	    } else {
528	        null_count = out_len - gatherBits(head.data, try validityBytes(src, src_end), src.offset, indices);
529	    }
530	
531	    const children = try takeChildren(allocator, src.children, src, indices);
532	    errdefer releaseChildren(allocator, children);
533	    var buffers: [1]buffer.SharedBuffer = .{if (!is_union and null_count == 0) blk: {
534	        head.deinit();
535	        break :blk buffer.SharedBuffer.empty;
536	    } else head.toShared(if (is_union) out_len else bitmap.byteLength(out_len)) catch return error.OutOfMemory};
537	    errdefer buffers[0].release();
538	
539	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
540	        .data_type = src.data_type,
541	        .length = out_len,
542	        .null_count = null_count,
543	        .buffers = buffers[0..],
544	        .children = children,
545	    }) catch return error.OutOfMemory;
546	}
