548	/// Direct take for fixed_size_list: validity by gatherBits, the child taken once with each
549	/// index expanded to its `list_size` child rows (null indices take null child rows).
550	fn takeFixedSizeListArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!ArrayRef {
551	    if (src.buffers.len != 1 or src.children.len != 1) return error.InvalidInput;
552	    const size = std.math.cast(usize, storageDataType(src.data_type).fixed_size_list.list_size) orelse return error.InvalidInput;
553	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
554	    const child_end = std.math.mul(usize, src_end, size) catch return error.Overflow;
555	    if (src.children[0].data().length < child_end) return error.InvalidInput;
556	    const src_validity = try validityBytes(src, src_end);
557	    try checkIndices(indices, src.length);
558	    const out_len = indices.len;
559	
560	    // A fixed-width child moves each row's values as one copy; other children are taken with the
561	    // expanded indices (dense ones as u32 child rows when the child fits: half the scratch).
562	    const child = src.children[0].data();
563	    const child_layout = storageDataType(child.data_type);
564	    const width = (try fixedByteWidth(child_layout)) orelse 0;
565	    const children = if (width > 0 and child_layout != .dictionary and child.buffers.len == 2) blk: {
566	        const one = allocator.alloc(ArrayRef, 1) catch return error.OutOfMemory;
567	        one[0] = takeFixedSizeListValues(allocator, child, width, size, src.offset, indices) catch |err| {
568	            allocator.free(one);
569	            return err;
570	        };
571	        break :blk one;
572	    } else if (!comptime isDense(@TypeOf(indices)))
573	        try takeExpandedChild(?usize, allocator, src, size, indices)
574	    else if (child_end <= std.math.maxInt(u32))
575	        try takeExpandedChild(u32, allocator, src, size, indices)
576	    else
577	        try takeExpandedChild(usize, allocator, src, size, indices);
578	    errdefer releaseChildren(allocator, children);
579	
580	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
581	    errdefer validity.deinit();
582	    const null_count = out_len - gatherBits(validity.data, src_validity, src.offset, indices);
583	    var buffers: [1]buffer.SharedBuffer = .{if (null_count == 0) blk: {
584	        validity.deinit();
585	        break :blk buffer.SharedBuffer.empty;
586	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory};
587	    errdefer buffers[0].release();
588	
589	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
590	        .data_type = src.data_type,
591	        .length = out_len,
592	        .null_count = null_count,
593	        .buffers = buffers[0..],
594	        .children = children,
595	    }) catch return error.OutOfMemory;
596	}
