598	/// The fixed-width child of a fixed_size_list taken by list rows: row `base + idx` moves its
599	/// `size` values with one copy and their validity bits one by one; null indices give null rows.
600	/// The caller checked the child covers every row.
601	fn takeFixedSizeListValues(allocator: std.mem.Allocator, child: *const array_mod.ArrayData, width: usize, size: usize, base: usize, indices: anytype) KernelError!ArrayRef {
602	    const child_end = std.math.add(usize, child.offset, child.length) catch return error.Overflow;
603	    const src_bytes = child.buffers[1].data;
604	    if (src_bytes.len < std.math.mul(usize, child_end, width) catch return error.Overflow) return error.InvalidInput;
605	    const child_validity = try validityBytes(child, child_end);
606	    const out_len = indices.len * size;
607	    const row_bytes = size * width;
608	
609	    var values = buffer.OwnedBuffer.initUninit(allocator, out_len * width) catch return error.OutOfMemory;
610	    errdefer values.deinit();
611	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
612	    errdefer validity.deinit();
613	    var valid: usize = 0;
614	    for (indices, 0..) |m, i| {
615	        const out = values.data[i * row_bytes ..][0..row_bytes];
616	        const idx = @as(?usize, m) orelse {
617	            @memset(out, 0);
618	            continue;
619	        };
620	        const first = child.offset + (base + idx) * size;
621	        @memcpy(out, src_bytes[first * width ..][0..row_bytes]);
622	        for (0..size) |k| {
623	            if (child_validity) |v| if (!bitmap.bitIsSet(v, first + k)) continue;
624	            bitmap.setBit(validity.data, i * size + k);
625	            valid += 1;
626	        }
627	    }
628	
629	    const null_count = out_len - valid;
630	    var buffers: [2]buffer.SharedBuffer = undefined;
631	    buffers[0] = if (null_count == 0) blk: {
632	        validity.deinit();
633	        break :blk buffer.SharedBuffer.empty;
634	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
635	    errdefer buffers[0].release();
636	    buffers[1] = values.toShared(out_len * width) catch return error.OutOfMemory;
637	    errdefer buffers[1].release();
638	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
639	        .data_type = child.data_type,
640	        .length = out_len,
641	        .null_count = null_count,
642	        .buffers = buffers[0..],
643	    }) catch return error.OutOfMemory;
644	}
