646	/// Takes child rows (offset + idx) * size + k, k < size, for every index (null: null child rows).
647	fn takeExpandedChild(comptime E: type, allocator: std.mem.Allocator, src: *const array_mod.ArrayData, size: usize, indices: anytype) KernelError![]ArrayRef {
648	    const child_indices = allocator.alloc(E, std.math.mul(usize, indices.len, size) catch return error.Overflow) catch return error.OutOfMemory;
649	    defer allocator.free(child_indices);
650	    for (indices, 0..) |m, i| {
651	        const dst = child_indices[i * size ..][0..size];
652	        if (@as(?usize, m)) |idx| {
653	            for (dst, (src.offset + idx) * size..) |*c, k| c.* = if (comptime E == u32) @intCast(k) else k;
654	        } else if (comptime E != ?usize) unreachable else @memset(dst, null);
655	    }
656	    return takeChildren(allocator, src.children, null, @as([]const E, child_indices));
657	}
