659	/// Direct take for list_view/large_list_view: gathers offsets and sizes (bounds-checked against
660	/// the child); the child is shared, not copied. Null indices are empty null views.
661	fn takeListViewArray(comptime T: type, allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!ArrayRef {
662	    if (src.buffers.len != 3 or src.children.len != 1) return error.InvalidInput;
663	    const offsets = src.buffers[1].typedSlice(T) catch return error.InvalidInput;
664	    const sizes = src.buffers[2].typedSlice(T) catch return error.InvalidInput;
665	    const child_len = src.children[0].data().length;
666	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
667	    if (offsets.len < src_end or sizes.len < src_end) return error.InvalidInput;
668	    const src_validity = try validityBytes(src, src_end);
669	    try checkIndices(indices, src.length);
670	    const out_len = indices.len;
671	
672	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, out_len * @sizeOf(T)) catch return error.OutOfMemory;
673	    errdefer out_offsets.deinit();
674	    var out_sizes = buffer.OwnedBuffer.initUninit(allocator, out_len * @sizeOf(T)) catch return error.OutOfMemory;
675	    errdefer out_sizes.deinit();
676	    for (indices, out_offsets.typedSlice(T)[0..out_len], out_sizes.typedSlice(T)[0..out_len]) |m, *o, *s| {
677	        const j = src.offset + (@as(?usize, m) orelse {
678	            o.* = 0;
679	            s.* = 0;
680	            continue;
681	        });
682	        const lo = std.math.cast(usize, offsets[j]) orelse return error.InvalidInput;
683	        const n = std.math.cast(usize, sizes[j]) orelse return error.InvalidInput;
684	        if (n > child_len or lo > child_len - n) return error.InvalidInput;
685	        o.* = offsets[j];
686	        s.* = sizes[j];
687	    }
688	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
689	    errdefer validity.deinit();
690	    const null_count = out_len - gatherBits(validity.data, src_validity, src.offset, indices);
691	
692	    const children = allocator.alloc(ArrayRef, 1) catch return error.OutOfMemory;
693	    errdefer allocator.free(children);
694	    var buffers: [3]buffer.SharedBuffer = undefined;
695	    buffers[0] = if (null_count == 0) blk: {
696	        validity.deinit();
697	        break :blk buffer.SharedBuffer.empty;
698	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
699	    errdefer buffers[0].release();
700	    buffers[1] = out_offsets.toShared(out_len * @sizeOf(T)) catch return error.OutOfMemory;
701	    errdefer buffers[1].release();
702	    buffers[2] = out_sizes.toShared(out_len * @sizeOf(T)) catch return error.OutOfMemory;
703	    errdefer buffers[2].release();
704	
705	    children[0] = src.children[0];
706	    const out = ArrayRef.fromOwnedInlineBuffers(allocator, .{
707	        .data_type = src.data_type,
708	        .length = out_len,
709	        .null_count = null_count,
710	        .buffers = buffers[0..],
711	        .children = children,
712	    }) catch return error.OutOfMemory;
713	    _ = children[0].retain();
714	    return out;
715	}
