717	/// Layouts with a direct take kernel; the rest (views, dense unions, run-end encoded) take row
718	/// by row (slice + concat).
719	fn hasTakeKernel(dt: DataType) bool {
720	    return switch (storageDataType(dt)) {
721	        .string_view, .binary_view, .dense_union, .run_end_encoded => false,
722	        else => true,
723	    };
724	}
