726	/// Direct take by layout; extension arrays take their storage layout and keep their type.
727	fn takeArray(allocator: std.mem.Allocator, src: *const array_mod.ArrayData, indices: anytype) KernelError!?ArrayRef {
728	    if (!hasTakeKernel(src.data_type)) return null;
729	    return switch (storageDataType(src.data_type)) {
730	        .null => blk: {
731	            try checkIndices(indices, src.length);
732	            break :blk ArrayRef.fromOwnedInlineBuffers(allocator, .{
733	                .data_type = src.data_type,
734	                .length = indices.len,
735	                .null_count = indices.len,
736	                .buffers = &.{},
737	            }) catch return error.OutOfMemory;
738	        },
739	        .string, .binary => try takeBinaryArray(i32, allocator, src, indices),
740	        .large_string, .large_binary => try takeBinaryArray(i64, allocator, src, indices),
741	        .list, .map => try takeListArray(i32, allocator, src, indices),
742	        .large_list => try takeListArray(i64, allocator, src, indices),
743	        .list_view => try takeListViewArray(i32, allocator, src, indices),
744	        .large_list_view => try takeListViewArray(i64, allocator, src, indices),
745	        .fixed_size_list => try takeFixedSizeListArray(allocator, src, indices),
746	        .struct_, .sparse_union => try takeStructLikeArray(allocator, src, indices),
747	        else => try takeFixedWidthArray(allocator, src, indices),
748	    };
749	}
