751	fn datumTakeArrayLikeNullable(
752	    allocator: std.mem.Allocator,
753	    datum: Datum,
754	    out_type: DataType,
755	    indices: anytype,
756	) KernelError!Datum {
757	    if (datum == .array) {
758	        if (try takeArray(allocator, datum.array.data(), indices)) |out| return Datum.fromArray(out);
759	    }
760	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
761	
762	    var pieces: std.ArrayList(ArrayRef) = .empty;
763	    defer {
764	        for (pieces.items) |*piece| piece.release();
765	        pieces.deinit(allocator);
766	    }
767	    try pieces.ensureTotalCapacity(allocator, indices.len);
768	
769	    for (indices) |choice| {
770	        const piece = if (@as(?usize, choice)) |idx|
771	            try accessors.datumElementArrayAt(allocator, datum, idx)
772	        else
773	            try builders.buildNullLikeArray(allocator, out_type, 1);
774	        pieces.appendAssumeCapacity(piece);
775	    }
776	
777	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
778	    return Datum.fromArray(out);
779	}
