781	fn predicateDecisionAt(predicate: Datum, logical_index: usize, options: FilterOptions) KernelError!PredicateDecision {
782	    return switch (predicate) {
783	        .scalar => |s| blk: {
784	            if (s.data_type != .bool) break :blk error.InvalidInput;
785	            if (s.isNull()) break :blk if (options.drop_nulls) .drop else .emit_null;
786	            break :blk if (s.value.bool) .keep else .drop;
787	        },
788	        .array => |arr| blk: {
789	            if (arr.data().data_type != .bool) break :blk error.InvalidInput;
790	            if (logical_index >= arr.data().length) break :blk error.InvalidInput;
791	            if (arr.data().isNull(logical_index)) break :blk if (options.drop_nulls) .drop else .emit_null;
792	            const bool_array = array_mod.BooleanArray{ .data = arr.data() };
793	            const keep = bool_array.value(logical_index) catch |err| return mapArrayReadError(err);
794	            break :blk if (keep) .keep else .drop;
795	        },
796	        .chunked => |chunks| blk: {
797	            if (chunks.dataType() != .bool) break :blk error.InvalidInput;
798	            const located = lookupChunkAt(chunks, logical_index) orelse break :blk error.InvalidInput;
799	            if (located.chunk.data().isNull(located.local_index)) break :blk if (options.drop_nulls) .drop else .emit_null;
800	            const bool_array = array_mod.BooleanArray{ .data = located.chunk.data() };
801	            const keep = bool_array.value(located.local_index) catch |err| return mapArrayReadError(err);
802	            break :blk if (keep) .keep else .drop;
803	        },
804	    };
805	}
