807	const SelectionByte = struct { emit: u8, valid: u8 };
808	
809	/// Rows `row .. row+8` of a bool predicate: which rows emit an entry and which of those are valid.
810	fn selectionByte(values: []const u8, validity: []const u8, bit: usize, rows_left: usize, drop_nulls: bool) SelectionByte {
811	    const tail_mask: u8 = if (rows_left >= 8) 0xFF else (@as(u8, 1) << @intCast(rows_left)) - 1;
812	    const valid = if (validity.len > 0) bitmap.byteAtBit(validity, bit) else 0xFF;
813	    var emit = bitmap.byteAtBit(values, bit) & valid;
814	    if (!drop_nulls) emit |= ~valid;
815	    return .{ .emit = emit & tail_mask, .valid = valid };
816	}
817	
818	/// Appends selections for rows [0, len) of a bool predicate array, 8 rows per step.
819	/// `base` is the logical index of the predicate's row 0.
820	fn appendBoolSelections(
821	    allocator: std.mem.Allocator,
822	    selections: anytype,
823	    pred: *const array_mod.ArrayData,
824	    len: usize,
825	    base: usize,
826	    options: FilterOptions,
827	) KernelError!void {
828	    if (pred.buffers.len < 2) return error.InvalidInput;
829	    const values = pred.buffers[1].data;
830	    const end = std.math.add(usize, pred.offset, len) catch return error.Overflow;
831	    if (bitmap.byteLength(end) > values.len) return error.InvalidInput;
832	    const validity: []const u8 = if (pred.validity()) |v| v.data else &.{};
833	    if (validity.len > 0 and bitmap.byteLength(end) > validity.len) return error.InvalidInput;
834	
835	    var count: usize = 0;
836	    var row: usize = 0;
837	    while (row < len) : (row += 8) {
838	        count += @popCount(selectionByte(values, validity, pred.offset + row, len - row, options.drop_nulls).emit);
839	    }
840	    try selections.ensureTotalCapacityPrecise(allocator, selections.items.len + count);
841	
842	    row = 0;
843	    while (row < len) : (row += 8) {
844	        const sb = selectionByte(values, validity, pred.offset + row, len - row, options.drop_nulls);
845	        var emit = sb.emit;
846	        while (emit != 0) : (emit &= emit - 1) {
847	            const bit: u3 = @intCast(@ctz(emit));
848	            const is_valid = (sb.valid >> bit) & 1 != 0;
