857	/// Build nullable selection indices from a boolean predicate.
858	///
859	/// `keep` emits the logical input index, `drop` emits nothing, and `emit_null`
860	/// emits `null` to preserve output row count for null-predicate semantics.
861	pub fn datumFilterSelectionIndices(
862	    allocator: std.mem.Allocator,
863	    predicate: Datum,
864	    logical_len: usize,
865	    options: FilterOptions,
866	) KernelError![]?usize {
867	    var selections: std.ArrayList(?usize) = .empty;
868	    defer selections.deinit(allocator);
869	
870	    switch (predicate) {
871	        .array => |arr| {
872	            if (arr.data().data_type != .bool) return error.InvalidInput;
873	            if (logical_len > arr.data().length) return error.InvalidInput;
874	            try appendBoolSelections(allocator, &selections, arr.data(), logical_len, 0, options);
875	        },
876	        .chunked => |chunks| {
877	            if (chunks.dataType() != .bool) return error.InvalidInput;
878	            var done: usize = 0;
879	            for (chunks.chunks()) |chunk| {
880	                if (done == logical_len) break;
881	                const take = @min(chunk.data().length, logical_len - done);
882	                try appendBoolSelections(allocator, &selections, chunk.data(), take, done, options);
883	                done += take;
884	            }
885	            if (done != logical_len) return error.InvalidInput;
886	        },
887	        .scalar => {
888	            var i: usize = 0;
889	            while (i < logical_len) : (i += 1) {
890	                switch (try predicateDecisionAt(predicate, i, options)) {
891	                    .drop => {},
892	                    .keep => try selections.append(allocator, i),
893	                    .emit_null => try selections.append(allocator, null),
894	                }
895	            }
896	        },
897	    }
898	    return selections.toOwnedSlice(allocator);
899	}
