901	/// Gather/take rows from a datum according to logical indices.
902	///
903	/// For chunked inputs this helper preserves chunked output and avoids forcing
904	/// concat pre-normalization.
905	pub fn datumTake(datum: Datum, indices: []const usize) KernelError!Datum {
906	    const allocator = common.inferDatumAllocator(datum) orelse std.heap.page_allocator;
907	    const out_type = datum.dataType();
908	
909	    if (indices.len == 0) {
910	        return switch (datum) {
911	            .chunked => |chunks| Datum.fromChunked(chunks.slice(allocator, 0, 0) catch |err| return common.mapChunkedError(err)),
912	            else => builders.datumBuildEmptyLikeWithAllocator(allocator, out_type),
913	        };
914	    }
915	
916	    return switch (datum) {
917	        .chunked => |chunks| datumTakeChunkedNullable(allocator, chunks, out_type, indices),
918	        else => datumTakeArrayLikeNullable(allocator, datum, out_type, indices),
919	    };
920	}
