927	    const allocator = common.inferDatumAllocator(datum) orelse std.heap.page_allocator;
928	    const out_type = datum.dataType();
929	    return switch (datum) {
930	        .chunked => |chunks| datumTakeChunkedNullable(allocator, chunks, out_type, indices),
931	        else => datumTakeArrayLikeNullable(allocator, datum, out_type, indices),
932	    };
