935	/// Row-wise selection primitive shared by choose/case_when/filter style operators.
936	///
937	/// `indices[i]` selects which entry in `values` contributes output row `i`.
938	/// Each candidate value may be array/chunked/scalar (scalar broadcasts).
939	pub fn datumSelect(indices: []const usize, values: []const Datum) KernelError!Datum {
940	    if (values.len == 0) return error.InvalidArity;
941	    if (!sameDataTypes(values)) return error.InvalidInput;
942	
943	    const output_len = try inferNaryExecLen(values);
944	    if (indices.len != output_len) return error.InvalidInput;
945	
946	    const allocator = common.inferDatumsAllocator(values);
947	    const out_type = values[0].dataType();
948	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
949	
950	    var pieces: std.ArrayList(ArrayRef) = .empty;
951	    defer {
952	        for (pieces.items) |*piece| piece.release();
953	        pieces.deinit(allocator);
954	    }
955	    try pieces.ensureTotalCapacity(allocator, indices.len);
956	
957	    for (indices, 0..) |choice, logical_index| {
958	        if (choice >= values.len) return error.InvalidInput;
959	        const piece = try accessors.datumElementArrayAt(allocator, values[choice], logical_index);
960	        pieces.appendAssumeCapacity(piece);
961	    }
962	
963	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
964	    return Datum.fromArray(out);
965	}
