1000	/// Chunk-aware filter helper for array/chunked/scalar datums with bool predicates.
1001	///
1002	/// This helper composes `datumFilterSelectionIndices` + `datumTakeNullable`,
1003	/// preserving chunked output when the input datum is chunked.
1004	pub fn datumFilterChunkAware(datum: Datum, predicate: Datum, options: FilterOptions) KernelError!Datum {
1005	    const input_len = try inferBinaryExecLen(datum, predicate);
1006	    const allocator = common.inferDatumsAllocator(&[_]Datum{ datum, predicate });
1007	    const selections = try datumFilterSelectionIndices(allocator, predicate, input_len, options);
1008	    defer allocator.free(selections);
1009	    return datumTakeNullable(datum, selections);
1010	}
