1012	/// Generic filter primitive for array/chunked/scalar datums with bool predicates.
1013	///
1014	/// This preserves the historical array-output shape for compatibility.
1015	pub fn datumFilter(datum: Datum, predicate: Datum, options: FilterOptions) KernelError!Datum {
1016	    const output_len = try inferBinaryExecLen(datum, predicate);
1017	    const allocator = common.inferDatumsAllocator(&[_]Datum{ datum, predicate });
1018	    const out_type = datum.dataType();
1019	
1020	    if (output_len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
1021	    if (predicate == .array and options.drop_nulls and output_len <= std.math.maxInt(u32)) {
1022	        // drop_nulls: every kept row is a valid index, so the selections are dense u32 (4 B per
1023	        // kept row, exact size) and the take runs the branch-free dense kernels.
1024	        const pred = predicate.array.data();
1025	        if (pred.data_type != .bool or output_len > pred.length) return error.InvalidInput;
1026	        var selections: std.ArrayList(u32) = .empty;
1027	        defer selections.deinit(allocator);
1028	        try appendBoolSelections(allocator, &selections, pred, output_len, 0, options);
1029	        return takeAsArray(allocator, datum, out_type, @as([]const u32, selections.items));
1030	    }
1031	    const selections = try datumFilterSelectionIndices(allocator, predicate, output_len, options);
1032	    defer allocator.free(selections);
1033	    return takeAsArray(allocator, datum, out_type, selections);
1034	}
