1036	/// Take with array output for every datum form (chunked pieces are concatenated once).
1037	fn takeAsArray(allocator: std.mem.Allocator, datum: Datum, out_type: DataType, indices: anytype) KernelError!Datum {
1038	    if (datum != .chunked) return datumTakeArrayLikeNullable(allocator, datum, out_type, indices);
1039	    var pieces: std.ArrayList(ArrayRef) = .empty;
1040	    defer releasePieces(allocator, &pieces);
1041	    try takeChunked(allocator, datum.chunked, out_type, indices, &pieces);
1042	    if (pieces.items.len == 1) return Datum.fromArray(pieces.items[0].retain());
1043	    if (pieces.items.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
1044	    return Datum.fromArray(concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err));
1045	}
