279	    fn validateByteViews(view_bytes: []const u8, start_index: usize, total_len: usize, variadic: []const SharedBuffer) ValidationError!void {
280	        if (view_bytes.len % 16 != 0) return error.InvalidOffsetBuffer;
281	        const view_count = view_bytes.len / 16;
282	        if (view_count < total_len) return error.BufferTooSmall;
283	
284	        var i: usize = start_index;
285	        while (i < total_len) : (i += 1) {
286	            const start = i * 16;
287	            const view = view_bytes[start .. start + 16];
288	            const len_u32 = readU32Le(view[0..4]);
289	            const len = std.math.cast(usize, len_u32) orelse return error.InvalidOffsets;
290	
291	            if (len <= 12) {
292	                const pad_start = 4 + len;
293	                for (view[pad_start..16]) |b| {
294	                    if (b != 0) return error.InvalidOffsets;
295	                }
296	                continue;
297	            }
298	
299	            const buffer_index = std.math.cast(usize, readU32Le(view[8..12])) orelse return error.InvalidOffsets;
300	            if (buffer_index >= variadic.len) return error.InvalidOffsets;
301	
302	            const byte_offset = std.math.cast(usize, readU32Le(view[12..16])) orelse return error.InvalidOffsets;
303	            const end = std.math.add(usize, byte_offset, len) catch return error.InvalidOffsets;
304	            if (end > variadic[buffer_index].len()) return error.InvalidOffsets;
305	            if (!std.mem.eql(u8, view[4..8], variadic[buffer_index].data[byte_offset .. byte_offset + 4])) {
306	                return error.InvalidOffsets;
307	            }
308	        }
309	    }
